```javascript
import * as THREE from 'three/webgpu';
import { MeshStandardNodeMaterial, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'stat-tile-home';
  group.position.set(-2.5, 1.6, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const timelines = [];
  const disposables = [];

  // Machined-metal surface panel behind gear mesh
  const panelGeo = new THREE.BoxGeometry(1.4, 0.9, 0.08);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.colorNode = color(0x16161d);
  panelMat.metalness = 0.5;
  panelMat.roughness = 0.55;
  panelMat.clearcoat = 0.2;
  const panel = new THREE.Mesh(panelGeo, panelMat);
  panel.position.z = -0.05;
  group.add(panel);
  disposables.push(panelGeo, panelMat);

  // Accent edge (hidden until focus)
  const edgeGeo = new THREE.BoxGeometry(1.44, 0.94, 0.02);
  const edgeMat = new MeshStandardNodeMaterial();
  edgeMat.colorNode = color(0xff2a38);
  edgeMat.metalness = 0.3;
  edgeMat.roughness = 0.4;
  edgeMat.transparent = true;
  edgeMat.opacity = 0.0;
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.09;
  group.add(edge);
  disposables.push(edgeGeo, edgeMat);

  // Load gear mesh
  let gearRoot = null;
  try {
    const gltf = ctx.glbLoader('/prism-mock/orrery/meshes/gear-a.glb');
    if (gltf && gltf.scene) {
      gearRoot = gltf.scene.clone(true);
      gearRoot.scale.setScalar(0.4);
      gearRoot.position.set(0, 0.15, 0.1);
      group.add(gearRoot);
    }
  } catch (e) {
    // mesh load failure is non-fatal
  }

  // Value + label text via MSDF font atlas
  let valueText = null;
  let labelText = null;
  if (ctx.fontAtlas && ctx.fontAtlas.createText) {
    valueText = ctx.fontAtlas.createText({
      text: '128',
      font: 'Lora',
      weight: 600,
      size: 0.34,
      color: 0xe8ecf2,
      atlas: 0,
      rect: [0, 0, 512, 320],
    });
    if (valueText) {
      valueText.position.set(-0.5, -0.05, 0.05);
      group.add(valueText);
    }

    labelText = ctx.fontAtlas.createText({
      text: 'ACTIVE PIECES',
      font: 'JetBrains Mono',
      weight: 400,
      size: 0.09,
      color: 0xe8ecf2,
      atlas: 0,
      rect: [0, 0, 512, 320],
    });
    if (labelText) {
      labelText.position.set(-0.5, -0.3, 0.05);
      group.add(labelText);
    }
  }

  // Apply cinematic primitives
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives && ctx.primitives[prim.name]) {
        ctx.primitives[prim.name](group, prim.params);
      }
    });
  }

  const baseY = group.position.y;

  // Hover: rise-in subtle lift
  function onHoverStart() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(edgeMat, { opacity: 0.6, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onHoverEnd() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY, duration: 0.5, ease: 'power2.out' }, 0);
    tl.to(edgeMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.12, ease: 'back.out' });
    timelines.push(tl);

    if (ctx.emit) {
      ctx.emit('hub-home.select', { source: 'stat-tile-home' });
    }
  }

  function onFocus() {
    const tl = gsap.timeline();
    tl.to(edgeMat, { opacity: 0.8, duration: 0.2, ease: 'power2.out' });
    timelines.push(tl);
  }

  function onBlur() {
    const tl = gsap.timeline();
    tl.to(edgeMat, { opacity: 0.0, duration: 0.2, ease: 'power2.out' });
    timelines.push(tl);
  }

  group.userData.handlers = {
    hover: onHoverStart,
    hoverStart: onHoverStart,
    hoverEnd: onHoverEnd,
    click: onClick,
    focus: onFocus,
    blur: onBlur,
  };

  group.userData.cleanup = function cleanup() {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });

    if (gearRoot) {
      gearRoot.traverse((child) => {
        if (child.geometry) child.geometry.dispose();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((m) => m.dispose());
          } else {
            child.material.dispose();
          }
        }
      });
    }

    if (valueText && valueText.userData && typeof valueText.userData.dispose === 'function') {
      valueText.userData.dispose();
    }
    if (labelText && labelText.userData && typeof labelText.userData.dispose === 'function') {
      labelText.userData.dispose();
    }
  };

  return group;
}
